const html        = document.documentElement;
const themeToggle = document.getElementById('themeToggle');
const langToggle  = document.getElementById('langToggle');

// ===== THÈME LIGHT / DARK =====
const savedTheme = localStorage.getItem('theme') || 'light';
html.setAttribute('data-theme', savedTheme);

themeToggle?.addEventListener('click', () => {
  const next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  localStorage.setItem('theme', next);
});

// ===== LANGUE FR / EN =====
const savedLang = localStorage.getItem('lang') || 'fr';
html.setAttribute('data-lang', savedLang);
if (langToggle) langToggle.textContent = savedLang === 'fr' ? 'EN' : 'FR';

langToggle?.addEventListener('click', () => {
  const next = html.getAttribute('data-lang') === 'fr' ? 'en' : 'fr';
  html.setAttribute('data-lang', next);
  localStorage.setItem('lang', next);
  langToggle.textContent = next === 'fr' ? 'EN' : 'FR';
});

// ===== NAVIGATION SPA =====
const views    = document.querySelectorAll('.view');
const navLinks = document.querySelectorAll('.nav-link');

function showView(name) {
  // Masquer toutes les vues
  views.forEach(v => v.classList.remove('active'));
  // Afficher la bonne vue
  const target = document.getElementById('view-' + name);
  if (target) {
    target.classList.add('active');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  // Mettre à jour les liens actifs
  navLinks.forEach(link => {
    link.classList.toggle('active', link.dataset.nav === name);
  });
}

// Clics sur tous les éléments [data-nav]
document.addEventListener('click', e => {
  const el = e.target.closest('[data-nav]');
  if (el) {
    e.preventDefault();
    showView(el.dataset.nav);
  }
});

// Bouton "En savoir plus" → scroll vers #about dans la vue home
document.addEventListener('click', e => {
  const el = e.target.closest('[data-scroll]');
  if (el) {
    e.preventDefault();
    const sectionId = el.dataset.scroll;
    showView('home');
    setTimeout(() => {
      const section = document.getElementById(sectionId);
      if (section) section.scrollIntoView({ behavior: 'smooth' });
    }, 50);
  }
});

